import statistics

def calculate_signal(strategy, closes):
    """Calculate trading signal based on strategy."""
    name = strategy["name"]
    params = strategy.get("params", {})

    if len(closes) < 60:
        return "hold"

    if name == "moving_average_crossover":
        short_window = params.get("short_window", 10)
        long_window = params.get("long_window", 50)

        if len(closes) < long_window + 1:
            return "hold"

        short_ma = sum(closes[-short_window:]) / short_window
        long_ma = sum(closes[-long_window:]) / long_window
        prev_short_ma = sum(closes[-short_window-1:-1]) / short_window
        prev_long_ma = sum(closes[-long_window-1:-1]) / long_window

        if prev_short_ma <= prev_long_ma and short_ma > long_ma:
            return "buy"
        elif prev_short_ma >= prev_long_ma and short_ma < long_ma:
            return "sell"
        return "hold"

    elif name == "mean_reversion_bollinger":
        window = params.get("window", 20)
        std_dev = params.get("std_dev", 2)

        if len(closes) < window:
            return "hold"

        ma = sum(closes[-window:]) / window
        std = statistics.stdev(closes[-window:])

        upper_band = ma + std_dev * std
        lower_band = ma - std_dev * std

        if closes[-1] < lower_band:
            return "buy"
        elif closes[-1] > upper_band:
            return "sell"
        return "hold"

    elif name == "roc_reversal":
        roc_period = params.get("roc_period", 12)
        overbought = params.get("overbought_threshold", 20)
        oversold = params.get("oversold_threshold", -20)

        if len(closes) < roc_period + 1:
            return "hold"

        roc = ((closes[-1] - closes[-roc_period-1]) / closes[-roc_period-1]) * 100

        if roc < oversold:
            return "buy"
        elif roc > overbought:
            return "sell"
        return "hold"

    elif name == "price_breakout":
        period = params.get("breakout_period", 20)
        sell_threshold = params.get("sell_threshold", 0.97)

        if len(closes) < period + 1:
            return "hold"

        recent_high = max(closes[-period-1:-1])

        if closes[-1] > recent_high:
            return "buy"
        elif closes[-1] < recent_high * sell_threshold:
            return "sell"
        return "hold"

    elif name == "ma_distance_reversion":
        ma_period = params.get("ma_period", 20)
        threshold = params.get("threshold", 0.05)

        if len(closes) < ma_period:
            return "hold"

        ma = sum(closes[-ma_period:]) / ma_period
        distance = (closes[-1] - ma) / ma

        if distance < -threshold:
            return "buy"
        elif distance > threshold:
            return "sell"
        return "hold"

    # Combined strategies
    elif name.startswith("mean_reversion_bollinger_plus_"):
        bollinger_params = params.get("mean_reversion_bollinger_params", {"window": 20, "std_dev": 2})
        signal1 = calculate_signal({"name": "mean_reversion_bollinger", "params": bollinger_params}, closes)

        if "moving_average_crossover" in name:
            ma_params = params.get("moving_average_crossover_params", {"short_window": 10, "long_window": 50})
            signal2 = calculate_signal({"name": "moving_average_crossover", "params": ma_params}, closes)
        elif "roc_reversal" in name:
            roc_params = params.get("roc_reversal_params", {"roc_period": 12, "overbought_threshold": 20, "oversold_threshold": -20})
            signal2 = calculate_signal({"name": "roc_reversal", "params": roc_params}, closes)
        elif "ma_distance_reversion" in name:
            ma_dist_params = params.get("ma_distance_reversion_params", {"ma_period": 20, "threshold": 0.05})
            signal2 = calculate_signal({"name": "ma_distance_reversion", "params": ma_dist_params}, closes)
        else:
            signal2 = "hold"

        if (signal1 == "buy" and signal2 in ["buy", "hold"]) or (signal1 == "hold" and signal2 == "buy"):
            return "buy"
        elif (signal1 == "sell" and signal2 in ["sell", "hold"]) or (signal1 == "hold" and signal2 == "sell"):
            return "sell"
        return "hold"

    return "hold"


async def solution(mcp_client):
    """Calculate mean_reversion_bollinger signal for VOO on 2025-08-12."""
    import json

    # Get historical prices
    result = await mcp_client.call_tool(
        "get_historical_stock_prices",
        {
            "ticker": "VOO",
