            "end_date": "2025-08-12",
            "interval": "1d"
        }
    )
    prices = json.loads(result)
    closes = [p["Close"] for p in prices]

    strategy = {"name": "mean_reversion_bollinger", "params": {"window": 20, "std_dev": 2}}
